# ! [doc = " Multi-producer, multi-consumer FIFO queue communication primitives."] # ! [doc = ""] # ! [doc = " This module provides message-based communication over channels, concretely"] # ! [doc = " defined by two types:"] # ! [doc = ""] # ! [doc = " * [`Sender`]"] # ! [doc = " * [`Receiver`]"] # ! [doc = ""] # ! [doc = " [`Sender`]s are used to send data to a set of [`Receiver`]s. Both"] # ! [doc = " sender and receiver are cloneable (multi-producer) such that many threads can send"] # ! [doc = " simultaneously to receivers (multi-consumer)."] # ! [doc = ""] # ! [doc = " These channels come in two flavors:"] # ! [doc = ""] # ! [doc = " 1. An asynchronous, infinitely buffered channel. The [`channel`] function"] # ! [doc = "    will return a `(Sender, Receiver)` tuple where all sends will be"] # ! [doc = "    **asynchronous** (they never block). The channel conceptually has an"] # ! [doc = "    infinite buffer."] # ! [doc = ""] # ! [doc = " 2. A synchronous, bounded channel. The [`sync_channel`] function will"] # ! [doc = "    return a `(Sender, Receiver)` tuple where the storage for pending"] # ! [doc = "    messages is a pre-allocated buffer of a fixed size. All sends will be"] # ! [doc = "    **synchronous** by blocking until there is buffer space available. Note"] # ! [doc = "    that a bound of 0 is allowed, causing the channel to become a \"rendezvous\""] # ! [doc = "    channel where each sender atomically hands off a message to a receiver."] # ! [doc = ""] # ! [doc = " [`send`]: Sender::send"] # ! [doc = ""] # ! [doc = " ## Disconnection"] # ! [doc = ""] # ! [doc = " The send and receive operations on channels will all return a [`Result`]"] # ! [doc = " indicating whether the operation succeeded or not. An unsuccessful operation"] # ! [doc = " is normally indicative of the other half of a channel having \"hung up\" by"] # ! [doc = " being dropped in its corresponding thread."] # ! [doc = ""] # ! [doc = " Once half of a channel has been deallocated, most operations can no longer"] # ! [doc = " continue to make progress, so [`Err`] will be returned. Many applications"] # ! [doc = " will continue to [`unwrap`] the results returned from this module,"] # ! [doc = " instigating a propagation of failure among threads if one unexpectedly dies."] # ! [doc = ""] # ! [doc = " [`unwrap`]: Result::unwrap"] # ! [doc = ""] # ! [doc = " # Examples"] # ! [doc = ""] # ! [doc = " Simple usage:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " #![feature(mpmc_channel)]"] # ! [doc = ""] # ! [doc = " use std::thread;"] # ! [doc = " use std::sync::mpmc::channel;"] # ! [doc = ""] # ! [doc = " // Create a simple streaming channel"] # ! [doc = " let (tx, rx) = channel();"] # ! [doc = " thread::spawn(move || {"] # ! [doc = "     tx.send(10).unwrap();"] # ! [doc = " });"] # ! [doc = " assert_eq!(rx.recv().unwrap(), 10);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Shared usage:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " #![feature(mpmc_channel)]"] # ! [doc = ""] # ! [doc = " use std::thread;"] # ! [doc = " use std::sync::mpmc::channel;"] # ! [doc = ""] # ! [doc = " thread::scope(|s| {"] # ! [doc = "     // Create a shared channel that can be sent along from many threads"] # ! [doc = "     // where tx is the sending half (tx for transmission), and rx is the receiving"] # ! [doc = "     // half (rx for receiving)."] # ! [doc = "     let (tx, rx) = channel();"] # ! [doc = "     for i in 0..10 {"] # ! [doc = "         let tx = tx.clone();"] # ! [doc = "         s.spawn(move || {"] # ! [doc = "             tx.send(i).unwrap();"] # ! [doc = "         });"] # ! [doc = "     }"] # ! [doc = ""] # ! [doc = "     for _ in 0..5 {"] # ! [doc = "         let rx1 = rx.clone();"] # ! [doc = "         let rx2 = rx.clone();"] # ! [doc = "         s.spawn(move || {"] # ! [doc = "             let j = rx1.recv().unwrap();"] # ! [doc = "             assert!(0 <= j && j < 10);"] # ! [doc = "         });"] # ! [doc = "         s.spawn(move || {"] # ! [doc = "             let j = rx2.recv().unwrap();"] # ! [doc = "             assert!(0 <= j && j < 10);"] # ! [doc = "         });"] # ! [doc = "     }"] # ! [doc = " })"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Propagating panics:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " #![feature(mpmc_channel)]"] # ! [doc = ""] # ! [doc = " use std::sync::mpmc::channel;"] # ! [doc = ""] # ! [doc = " // The call to recv() will return an error because the channel has already"] # ! [doc = " // hung up (or been deallocated)"] # ! [doc = " let (tx, rx) = channel::<i32>();"] # ! [doc = " drop(tx);"] # ! [doc = " assert!(rx.recv().is_err());"] # ! [doc = " ```"] use split_decls_genesis :: ourprelude :: * ; mod array ; mod context ; mod counter ; mod error ; mod list ; mod select ; mod utils ; mod waker ; mod zero ; pub use error :: * ; use crate :: fmt ; use crate :: panic :: { RefUnwindSafe , UnwindSafe } ; use crate :: time :: { Duration , Instant } ; #[doc = " Creates a new asynchronous channel, returning the sender/receiver halves."] #[doc = ""] #[doc = " All data sent on the [`Sender`] will become available on the [`Receiver`] in"] #[doc = " the same order as it was sent, and no [`send`] will block the calling thread"] #[doc = " (this channel has an \"infinite buffer\", unlike [`sync_channel`], which will"] #[doc = " block after its buffer limit is reached). [`recv`] will block until a message"] #[doc = " is available while there is at least one [`Sender`] alive (including clones)."] #[doc = ""] #[doc = " The [`Sender`] can be cloned to [`send`] to the same channel multiple times."] #[doc = " The [`Receiver`] also can be cloned to have multi receivers."] #[doc = ""] #[doc = " If the [`Receiver`] is disconnected while trying to [`send`] with the"] #[doc = " [`Sender`], the [`send`] method will return a [`SendError`]. Similarly, if the"] #[doc = " [`Sender`] is disconnected while trying to [`recv`], the [`recv`] method will"] #[doc = " return a [`RecvError`]."] #[doc = ""] #[doc = " [`send`]: Sender::send"] #[doc = " [`recv`]: Receiver::recv"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (sender, receiver) = channel();"] #[doc = ""] #[doc = " // Spawn off an expensive computation"] #[doc = " thread::spawn(move || {"] #[doc = " #   fn expensive_computation() {}"] #[doc = "     sender.send(expensive_computation()).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " // Do some useful work for a while"] #[doc = ""] #[doc = " // Let's see what that answer was"] #[doc = " println!(\"{:?}\", receiver.recv().unwrap());"] #[doc = " ```"] #[must_use] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn channel < T > () -> (Sender < T > , Receiver < T >) { let (s , r) = counter :: new (list :: Channel :: new ()) ; let s = Sender { flavor : SenderFlavor :: List (s) } ; let r = Receiver { flavor : ReceiverFlavor :: List (r) } ; (s , r) } #[doc = " Creates a new synchronous, bounded channel."] #[doc = ""] #[doc = " All data sent on the [`Sender`] will become available on the [`Receiver`]"] #[doc = " in the same order as it was sent. Like asynchronous [`channel`]s, the"] #[doc = " [`Receiver`] will block until a message becomes available. `sync_channel`"] #[doc = " differs greatly in the semantics of the sender, however."] #[doc = ""] #[doc = " This channel has an internal buffer on which messages will be queued."] #[doc = " `bound` specifies the buffer size. When the internal buffer becomes full,"] #[doc = " future sends will *block* waiting for the buffer to open up. Note that a"] #[doc = " buffer size of 0 is valid, in which case this becomes \"rendezvous channel\""] #[doc = " where each [`send`] will not return until a [`recv`] is paired with it."] #[doc = ""] #[doc = " The [`Sender`] can be cloned to [`send`] to the same channel multiple"] #[doc = " times. The [`Receiver`] also can be cloned to have multi receivers."] #[doc = ""] #[doc = " Like asynchronous channels, if the [`Receiver`] is disconnected while trying"] #[doc = " to [`send`] with the [`Sender`], the [`send`] method will return a"] #[doc = " [`SendError`]. Similarly, If the [`Sender`] is disconnected while trying"] #[doc = " to [`recv`], the [`recv`] method will return a [`RecvError`]."] #[doc = ""] #[doc = " [`send`]: Sender::send"] #[doc = " [`recv`]: Receiver::recv"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::sync::mpsc::sync_channel;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (sender, receiver) = sync_channel(1);"] #[doc = ""] #[doc = " // this returns immediately"] #[doc = " sender.send(1).unwrap();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     // this will block until the previous message has been received"] #[doc = "     sender.send(2).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " assert_eq!(receiver.recv().unwrap(), 1);"] #[doc = " assert_eq!(receiver.recv().unwrap(), 2);"] #[doc = " ```"] #[must_use] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn sync_channel < T > (cap : usize) -> (Sender < T > , Receiver < T >) { if cap == 0 { let (s , r) = counter :: new (zero :: Channel :: new ()) ; let s = Sender { flavor : SenderFlavor :: Zero (s) } ; let r = Receiver { flavor : ReceiverFlavor :: Zero (r) } ; (s , r) } else { let (s , r) = counter :: new (array :: Channel :: with_capacity (cap)) ; let s = Sender { flavor : SenderFlavor :: Array (s) } ; let r = Receiver { flavor : ReceiverFlavor :: Array (r) } ; (s , r) } } #[doc = " The sending-half of Rust's synchronous [`channel`] type."] #[doc = ""] #[doc = " Messages can be sent through this channel with [`send`]."] #[doc = ""] #[doc = " Note: all senders (the original and its clones) need to be dropped for the receiver"] #[doc = " to stop blocking to receive messages with [`Receiver::recv`]."] #[doc = ""] #[doc = " [`send`]: Sender::send"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (sender, receiver) = channel();"] #[doc = " let sender2 = sender.clone();"] #[doc = ""] #[doc = " // First thread owns sender"] #[doc = " thread::spawn(move || {"] #[doc = "     sender.send(1).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " // Second thread owns sender2"] #[doc = " thread::spawn(move || {"] #[doc = "     sender2.send(2).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " let msg = receiver.recv().unwrap();"] #[doc = " let msg2 = receiver.recv().unwrap();"] #[doc = ""] #[doc = " assert_eq!(3, msg + msg2);"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub struct Sender < T > { flavor : SenderFlavor < T > , } #[doc = " Sender flavors."] enum SenderFlavor < T > { #[doc = " Bounded channel based on a preallocated array."] Array (counter :: Sender < array :: Channel < T > >) , #[doc = " Unbounded channel implemented as a linked list."] List (counter :: Sender < list :: Channel < T > >) , #[doc = " Zero-capacity channel."] Zero (counter :: Sender < zero :: Channel < T > >) , } #[unstable (feature = "mpmc_channel" , issue = "126840")] unsafe impl < T : Send > Send for Sender < T > { } #[unstable (feature = "mpmc_channel" , issue = "126840")] unsafe impl < T : Send > Sync for Sender < T > { } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > UnwindSafe for Sender < T > { } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > RefUnwindSafe for Sender < T > { } impl < T > Sender < T > { #[doc = " Attempts to send a message into the channel without blocking."] #[doc = ""] #[doc = " This method will either send a message into the channel immediately or return an error if"] #[doc = " the channel is full or disconnected. The returned error contains the original message."] #[doc = ""] #[doc = " If called on a zero-capacity channel, this method will send the message only if there"] #[doc = " happens to be a receive operation on the other side of the channel at the same time."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::{channel, Receiver, Sender};"] #[doc = ""] #[doc = " let (sender, _receiver): (Sender<i32>, Receiver<i32>) = channel();"] #[doc = ""] #[doc = " assert!(sender.try_send(1).is_ok());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn try_send (& self , msg : T) -> Result < () , TrySendError < T > > { match & self . flavor { SenderFlavor :: Array (chan) => chan . try_send (msg) , SenderFlavor :: List (chan) => chan . try_send (msg) , SenderFlavor :: Zero (chan) => chan . try_send (msg) , } } #[doc = " Attempts to send a value on this channel, returning it back if it could"] #[doc = " not be sent."] #[doc = ""] #[doc = " A successful send occurs when it is determined that the other end of"] #[doc = " the channel has not hung up already. An unsuccessful send would be one"] #[doc = " where the corresponding receiver has already been deallocated. Note"] #[doc = " that a return value of [`Err`] means that the data will never be"] #[doc = " received, but a return value of [`Ok`] does *not* mean that the data"] #[doc = " will be received. It is possible for the corresponding receiver to"] #[doc = " hang up immediately after this function returns [`Ok`]. However, if"] #[doc = " the channel is zero-capacity, it acts as a rendezvous channel and a"] #[doc = " return value of [`Ok`] means that the data has been received."] #[doc = ""] #[doc = " If the channel is full and not disconnected, this call will block until"] #[doc = " the send operation can proceed. If the channel becomes disconnected,"] #[doc = " this call will wake up and return an error. The returned error contains"] #[doc = " the original message."] #[doc = ""] #[doc = " If called on a zero-capacity channel, this method will wait for a receive"] #[doc = " operation to appear on the other side of the channel."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = ""] #[doc = " let (tx, rx) = channel();"] #[doc = ""] #[doc = " // This send is always successful"] #[doc = " tx.send(1).unwrap();"] #[doc = ""] #[doc = " // This send will fail because the receiver is gone"] #[doc = " drop(rx);"] #[doc = " assert!(tx.send(1).is_err());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn send (& self , msg : T) -> Result < () , SendError < T > > { match & self . flavor { SenderFlavor :: Array (chan) => chan . send (msg , None) , SenderFlavor :: List (chan) => chan . send (msg , None) , SenderFlavor :: Zero (chan) => chan . send (msg , None) , } . map_err (| err | match err { SendTimeoutError :: Disconnected (msg) => SendError (msg) , SendTimeoutError :: Timeout (_) => unreachable ! () , }) } } impl < T > Sender < T > { #[doc = " Waits for a message to be sent into the channel, but only for a limited time."] #[doc = ""] #[doc = " If the channel is full and not disconnected, this call will block until the send operation"] #[doc = " can proceed or the operation times out. If the channel becomes disconnected, this call will"] #[doc = " wake up and return an error. The returned error contains the original message."] #[doc = ""] #[doc = " If called on a zero-capacity channel, this method will wait for a receive operation to"] #[doc = " appear on the other side of the channel."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::time::Duration;"] #[doc = ""] #[doc = " let (tx, rx) = channel();"] #[doc = ""] #[doc = " tx.send_timeout(1, Duration::from_millis(400)).unwrap();"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn send_timeout (& self , msg : T , timeout : Duration) -> Result < () , SendTimeoutError < T > > { match Instant :: now () . checked_add (timeout) { Some (deadline) => self . send_deadline (msg , deadline) , None => self . send (msg) . map_err (SendTimeoutError :: from) , } } #[doc = " Waits for a message to be sent into the channel, but only until a given deadline."] #[doc = ""] #[doc = " If the channel is full and not disconnected, this call will block until the send operation"] #[doc = " can proceed or the operation times out. If the channel becomes disconnected, this call will"] #[doc = " wake up and return an error. The returned error contains the original message."] #[doc = ""] #[doc = " If called on a zero-capacity channel, this method will wait for a receive operation to"] #[doc = " appear on the other side of the channel."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::time::{Duration, Instant};"] #[doc = ""] #[doc = " let (tx, rx) = channel();"] #[doc = ""] #[doc = " let t = Instant::now() + Duration::from_millis(400);"] #[doc = " tx.send_deadline(1, t).unwrap();"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn send_deadline (& self , msg : T , deadline : Instant) -> Result < () , SendTimeoutError < T > > { match & self . flavor { SenderFlavor :: Array (chan) => chan . send (msg , Some (deadline)) , SenderFlavor :: List (chan) => chan . send (msg , Some (deadline)) , SenderFlavor :: Zero (chan) => chan . send (msg , Some (deadline)) , } } #[doc = " Returns `true` if the channel is empty."] #[doc = ""] #[doc = " Note: Zero-capacity channels are always empty."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, _recv) = mpmc::channel();"] #[doc = ""] #[doc = " let tx1 = send.clone();"] #[doc = " let tx2 = send.clone();"] #[doc = ""] #[doc = " assert!(tx1.is_empty());"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     tx2.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert!(!tx1.is_empty());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn is_empty (& self) -> bool { match & self . flavor { SenderFlavor :: Array (chan) => chan . is_empty () , SenderFlavor :: List (chan) => chan . is_empty () , SenderFlavor :: Zero (chan) => chan . is_empty () , } } #[doc = " Returns `true` if the channel is full."] #[doc = ""] #[doc = " Note: Zero-capacity channels are always full."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, _recv) = mpmc::sync_channel(1);"] #[doc = ""] #[doc = " let (tx1, tx2) = (send.clone(), send.clone());"] #[doc = " assert!(!tx1.is_full());"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     tx2.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert!(tx1.is_full());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn is_full (& self) -> bool { match & self . flavor { SenderFlavor :: Array (chan) => chan . is_full () , SenderFlavor :: List (chan) => chan . is_full () , SenderFlavor :: Zero (chan) => chan . is_full () , } } #[doc = " Returns the number of messages in the channel."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, _recv) = mpmc::channel();"] #[doc = " let (tx1, tx2) = (send.clone(), send.clone());"] #[doc = ""] #[doc = " assert_eq!(tx1.len(), 0);"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     tx2.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert_eq!(tx1.len(), 1);"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn len (& self) -> usize { match & self . flavor { SenderFlavor :: Array (chan) => chan . len () , SenderFlavor :: List (chan) => chan . len () , SenderFlavor :: Zero (chan) => chan . len () , } } #[doc = " If the channel is bounded, returns its capacity."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, _recv) = mpmc::sync_channel(3);"] #[doc = " let (tx1, tx2) = (send.clone(), send.clone());"] #[doc = ""] #[doc = " assert_eq!(tx1.capacity(), Some(3));"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     tx2.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert_eq!(tx1.capacity(), Some(3));"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn capacity (& self) -> Option < usize > { match & self . flavor { SenderFlavor :: Array (chan) => chan . capacity () , SenderFlavor :: List (chan) => chan . capacity () , SenderFlavor :: Zero (chan) => chan . capacity () , } } #[doc = " Returns `true` if senders belong to the same channel."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = ""] #[doc = " let (tx1, _) = mpmc::channel::<i32>();"] #[doc = " let (tx2, _) = mpmc::channel::<i32>();"] #[doc = ""] #[doc = " assert!(tx1.same_channel(&tx1));"] #[doc = " assert!(!tx1.same_channel(&tx2));"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn same_channel (& self , other : & Sender < T >) -> bool { match (& self . flavor , & other . flavor) { (SenderFlavor :: Array (a) , SenderFlavor :: Array (b)) => a == b , (SenderFlavor :: List (a) , SenderFlavor :: List (b)) => a == b , (SenderFlavor :: Zero (a) , SenderFlavor :: Zero (b)) => a == b , _ => false , } } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > Drop for Sender < T > { fn drop (& mut self) { unsafe { match & self . flavor { SenderFlavor :: Array (chan) => chan . release (| c | c . disconnect_senders ()) , SenderFlavor :: List (chan) => chan . release (| c | c . disconnect_senders ()) , SenderFlavor :: Zero (chan) => chan . release (| c | c . disconnect ()) , } } } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > Clone for Sender < T > { fn clone (& self) -> Self { let flavor = match & self . flavor { SenderFlavor :: Array (chan) => SenderFlavor :: Array (chan . acquire ()) , SenderFlavor :: List (chan) => SenderFlavor :: List (chan . acquire ()) , SenderFlavor :: Zero (chan) => SenderFlavor :: Zero (chan . acquire ()) , } ; Sender { flavor } } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > fmt :: Debug for Sender < T > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . pad ("Sender { .. }") } } #[doc = " The receiving half of Rust's [`channel`] (or [`sync_channel`]) type."] #[doc = " Different threads can share this [`Receiver`] by cloning it."] #[doc = ""] #[doc = " Messages sent to the channel can be retrieved using [`recv`]."] #[doc = ""] #[doc = " [`recv`]: Receiver::recv"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = " use std::time::Duration;"] #[doc = ""] #[doc = " let (send, recv) = channel();"] #[doc = ""] #[doc = " let tx_thread = thread::spawn(move || {"] #[doc = "     send.send(\"Hello world!\").unwrap();"] #[doc = "     thread::sleep(Duration::from_secs(2)); // block for two seconds"] #[doc = "     send.send(\"Delayed for 2 seconds\").unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " let (rx1, rx2) = (recv.clone(), recv.clone());"] #[doc = " let rx_thread_1 = thread::spawn(move || {"] #[doc = "     println!(\"{}\", rx1.recv().unwrap()); // Received immediately"] #[doc = " });"] #[doc = " let rx_thread_2 = thread::spawn(move || {"] #[doc = "     println!(\"{}\", rx2.recv().unwrap()); // Received after 2 seconds"] #[doc = " });"] #[doc = ""] #[doc = " tx_thread.join().unwrap();"] #[doc = " rx_thread_1.join().unwrap();"] #[doc = " rx_thread_2.join().unwrap();"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub struct Receiver < T > { flavor : ReceiverFlavor < T > , } #[doc = " An iterator over messages on a [`Receiver`], created by [`iter`]."] #[doc = ""] #[doc = " This iterator will block whenever [`next`] is called,"] #[doc = " waiting for a new message, and [`None`] will be returned"] #[doc = " when the corresponding channel has hung up."] #[doc = ""] #[doc = " [`iter`]: Receiver::iter"] #[doc = " [`next`]: Iterator::next"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = channel();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = "     send.send(2u8).unwrap();"] #[doc = "     send.send(3u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " for x in recv.iter() {"] #[doc = "     println!(\"Got: {x}\");"] #[doc = " }"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] #[derive (Debug)] pub struct Iter < 'a , T : 'a > { rx : & 'a Receiver < T > , } #[doc = " An iterator that attempts to yield all pending values for a [`Receiver`],"] #[doc = " created by [`try_iter`]."] #[doc = ""] #[doc = " [`None`] will be returned when there are no pending values remaining or"] #[doc = " if the corresponding channel has hung up."] #[doc = ""] #[doc = " This iterator will never block the caller in order to wait for data to"] #[doc = " become available. Instead, it will return [`None`]."] #[doc = ""] #[doc = " [`try_iter`]: Receiver::try_iter"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = " use std::time::Duration;"] #[doc = ""] #[doc = " let (sender, receiver) = channel();"] #[doc = ""] #[doc = " // Nothing is in the buffer yet"] #[doc = " assert!(receiver.try_iter().next().is_none());"] #[doc = " println!(\"Nothing in the buffer...\");"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     sender.send(1).unwrap();"] #[doc = "     sender.send(2).unwrap();"] #[doc = "     sender.send(3).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " println!(\"Going to sleep...\");"] #[doc = " thread::sleep(Duration::from_secs(2)); // block for two seconds"] #[doc = ""] #[doc = " for x in receiver.try_iter() {"] #[doc = "     println!(\"Got: {x}\");"] #[doc = " }"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] #[derive (Debug)] pub struct TryIter < 'a , T : 'a > { rx : & 'a Receiver < T > , } #[doc = " An owning iterator over messages on a [`Receiver`],"] #[doc = " created by [`into_iter`]."] #[doc = ""] #[doc = " This iterator will block whenever [`next`]"] #[doc = " is called, waiting for a new message, and [`None`] will be"] #[doc = " returned if the corresponding channel has hung up."] #[doc = ""] #[doc = " [`into_iter`]: Receiver::into_iter"] #[doc = " [`next`]: Iterator::next"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = channel();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = "     send.send(2u8).unwrap();"] #[doc = "     send.send(3u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " for x in recv.into_iter() {"] #[doc = "     println!(\"Got: {x}\");"] #[doc = " }"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] #[derive (Debug)] pub struct IntoIter < T > { rx : Receiver < T > , } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < 'a , T > Iterator for Iter < 'a , T > { type Item = T ; fn next (& mut self) -> Option < T > { self . rx . recv () . ok () } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < 'a , T > Iterator for TryIter < 'a , T > { type Item = T ; fn next (& mut self) -> Option < T > { self . rx . try_recv () . ok () } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < 'a , T > IntoIterator for & 'a Receiver < T > { type Item = T ; type IntoIter = Iter < 'a , T > ; fn into_iter (self) -> Iter < 'a , T > { self . iter () } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > Iterator for IntoIter < T > { type Item = T ; fn next (& mut self) -> Option < T > { self . rx . recv () . ok () } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > IntoIterator for Receiver < T > { type Item = T ; type IntoIter = IntoIter < T > ; fn into_iter (self) -> IntoIter < T > { IntoIter { rx : self } } } #[doc = " Receiver flavors."] enum ReceiverFlavor < T > { #[doc = " Bounded channel based on a preallocated array."] Array (counter :: Receiver < array :: Channel < T > >) , #[doc = " Unbounded channel implemented as a linked list."] List (counter :: Receiver < list :: Channel < T > >) , #[doc = " Zero-capacity channel."] Zero (counter :: Receiver < zero :: Channel < T > >) , } #[unstable (feature = "mpmc_channel" , issue = "126840")] unsafe impl < T : Send > Send for Receiver < T > { } #[unstable (feature = "mpmc_channel" , issue = "126840")] unsafe impl < T : Send > Sync for Receiver < T > { } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > UnwindSafe for Receiver < T > { } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > RefUnwindSafe for Receiver < T > { } impl < T > Receiver < T > { #[doc = " Attempts to receive a message from the channel without blocking."] #[doc = ""] #[doc = " This method will never block the caller in order to wait for data to"] #[doc = " become available. Instead, this will always return immediately with a"] #[doc = " possible option of pending data on the channel."] #[doc = ""] #[doc = " If called on a zero-capacity channel, this method will receive a message only if there"] #[doc = " happens to be a send operation on the other side of the channel at the same time."] #[doc = ""] #[doc = " This is useful for a flavor of \"optimistic check\" before deciding to"] #[doc = " block on a receiver."] #[doc = ""] #[doc = " Compared with [`recv`], this function has two failure cases instead of one"] #[doc = " (one for disconnection, one for an empty buffer)."] #[doc = ""] #[doc = " [`recv`]: Self::recv"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::{Receiver, channel};"] #[doc = ""] #[doc = " let (_, receiver): (_, Receiver<i32>) = channel();"] #[doc = ""] #[doc = " assert!(receiver.try_recv().is_err());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn try_recv (& self) -> Result < T , TryRecvError > { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . try_recv () , ReceiverFlavor :: List (chan) => chan . try_recv () , ReceiverFlavor :: Zero (chan) => chan . try_recv () , } } #[doc = " Attempts to wait for a value on this receiver, returning an error if the"] #[doc = " corresponding channel has hung up."] #[doc = ""] #[doc = " This function will always block the current thread if there is no data"] #[doc = " available and it's possible for more data to be sent (at least one sender"] #[doc = " still exists). Once a message is sent to the corresponding [`Sender`],"] #[doc = " this receiver will wake up and return that message."] #[doc = ""] #[doc = " If the corresponding [`Sender`] has disconnected, or it disconnects while"] #[doc = " this call is blocking, this call will wake up and return [`Err`] to"] #[doc = " indicate that no more messages can ever be received on this channel."] #[doc = " However, since channels are buffered, messages sent before the disconnect"] #[doc = " will still be properly received."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert_eq!(Ok(1), recv.recv());"] #[doc = " ```"] #[doc = ""] #[doc = " Buffering behavior:"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = " use std::sync::mpmc::RecvError;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = "     send.send(2).unwrap();"] #[doc = "     send.send(3).unwrap();"] #[doc = "     drop(send);"] #[doc = " });"] #[doc = ""] #[doc = " // wait for the thread to join so we ensure the sender is dropped"] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert_eq!(Ok(1), recv.recv());"] #[doc = " assert_eq!(Ok(2), recv.recv());"] #[doc = " assert_eq!(Ok(3), recv.recv());"] #[doc = " assert_eq!(Err(RecvError), recv.recv());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn recv (& self) -> Result < T , RecvError > { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . recv (None) , ReceiverFlavor :: List (chan) => chan . recv (None) , ReceiverFlavor :: Zero (chan) => chan . recv (None) , } . map_err (| _ | RecvError) } #[doc = " Attempts to wait for a value on this receiver, returning an error if the"] #[doc = " corresponding channel has hung up, or if it waits more than `timeout`."] #[doc = ""] #[doc = " This function will always block the current thread if there is no data"] #[doc = " available and it's possible for more data to be sent (at least one sender"] #[doc = " still exists). Once a message is sent to the corresponding [`Sender`],"] #[doc = " this receiver will wake up and return that message."] #[doc = ""] #[doc = " If the corresponding [`Sender`] has disconnected, or it disconnects while"] #[doc = " this call is blocking, this call will wake up and return [`Err`] to"] #[doc = " indicate that no more messages can ever be received on this channel."] #[doc = " However, since channels are buffered, messages sent before the disconnect"] #[doc = " will still be properly received."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Successfully receiving value before encountering timeout:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::thread;"] #[doc = " use std::time::Duration;"] #[doc = " use std::sync::mpmc;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     send.send('a').unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " assert_eq!("] #[doc = "     recv.recv_timeout(Duration::from_millis(400)),"] #[doc = "     Ok('a')"] #[doc = " );"] #[doc = " ```"] #[doc = ""] #[doc = " Receiving an error upon reaching timeout:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::thread;"] #[doc = " use std::time::Duration;"] #[doc = " use std::sync::mpmc;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     thread::sleep(Duration::from_millis(800));"] #[doc = "     send.send('a').unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " assert_eq!("] #[doc = "     recv.recv_timeout(Duration::from_millis(400)),"] #[doc = "     Err(mpmc::RecvTimeoutError::Timeout)"] #[doc = " );"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn recv_timeout (& self , timeout : Duration) -> Result < T , RecvTimeoutError > { match Instant :: now () . checked_add (timeout) { Some (deadline) => self . recv_deadline (deadline) , None => self . recv () . map_err (RecvTimeoutError :: from) , } } #[doc = " Attempts to wait for a value on this receiver, returning an error if the"] #[doc = " corresponding channel has hung up, or if `deadline` is reached."] #[doc = ""] #[doc = " This function will always block the current thread if there is no data"] #[doc = " available and it's possible for more data to be sent. Once a message is"] #[doc = " sent to the corresponding [`Sender`], then this receiver will wake up"] #[doc = " and return that message."] #[doc = ""] #[doc = " If the corresponding [`Sender`] has disconnected, or it disconnects while"] #[doc = " this call is blocking, this call will wake up and return [`Err`] to"] #[doc = " indicate that no more messages can ever be received on this channel."] #[doc = " However, since channels are buffered, messages sent before the disconnect"] #[doc = " will still be properly received."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Successfully receiving value before reaching deadline:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::thread;"] #[doc = " use std::time::{Duration, Instant};"] #[doc = " use std::sync::mpmc;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     send.send('a').unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " assert_eq!("] #[doc = "     recv.recv_deadline(Instant::now() + Duration::from_millis(400)),"] #[doc = "     Ok('a')"] #[doc = " );"] #[doc = " ```"] #[doc = ""] #[doc = " Receiving an error upon reaching deadline:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::thread;"] #[doc = " use std::time::{Duration, Instant};"] #[doc = " use std::sync::mpmc;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     thread::sleep(Duration::from_millis(800));"] #[doc = "     send.send('a').unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " assert_eq!("] #[doc = "     recv.recv_deadline(Instant::now() + Duration::from_millis(400)),"] #[doc = "     Err(mpmc::RecvTimeoutError::Timeout)"] #[doc = " );"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn recv_deadline (& self , deadline : Instant) -> Result < T , RecvTimeoutError > { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . recv (Some (deadline)) , ReceiverFlavor :: List (chan) => chan . recv (Some (deadline)) , ReceiverFlavor :: Zero (chan) => chan . recv (Some (deadline)) , } } #[doc = " Returns an iterator that will attempt to yield all pending values."] #[doc = " It will return `None` if there are no more pending values or if the"] #[doc = " channel has hung up. The iterator will never [`panic!`] or block the"] #[doc = " user by waiting for values."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = " use std::time::Duration;"] #[doc = ""] #[doc = " let (sender, receiver) = channel();"] #[doc = ""] #[doc = " // nothing is in the buffer yet"] #[doc = " assert!(receiver.try_iter().next().is_none());"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     thread::sleep(Duration::from_secs(1));"] #[doc = "     sender.send(1).unwrap();"] #[doc = "     sender.send(2).unwrap();"] #[doc = "     sender.send(3).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " // nothing is in the buffer yet"] #[doc = " assert!(receiver.try_iter().next().is_none());"] #[doc = ""] #[doc = " // block for two seconds"] #[doc = " thread::sleep(Duration::from_secs(2));"] #[doc = ""] #[doc = " let mut iter = receiver.try_iter();"] #[doc = " assert_eq!(iter.next(), Some(1));"] #[doc = " assert_eq!(iter.next(), Some(2));"] #[doc = " assert_eq!(iter.next(), Some(3));"] #[doc = " assert_eq!(iter.next(), None);"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn try_iter (& self) -> TryIter < '_ , T > { TryIter { rx : self } } } impl < T > Receiver < T > { #[doc = " Returns `true` if the channel is empty."] #[doc = ""] #[doc = " Note: Zero-capacity channels are always empty."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = ""] #[doc = " assert!(recv.is_empty());"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert!(!recv.is_empty());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn is_empty (& self) -> bool { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . is_empty () , ReceiverFlavor :: List (chan) => chan . is_empty () , ReceiverFlavor :: Zero (chan) => chan . is_empty () , } } #[doc = " Returns `true` if the channel is full."] #[doc = ""] #[doc = " Note: Zero-capacity channels are always full."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::sync_channel(1);"] #[doc = ""] #[doc = " assert!(!recv.is_full());"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert!(recv.is_full());"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn is_full (& self) -> bool { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . is_full () , ReceiverFlavor :: List (chan) => chan . is_full () , ReceiverFlavor :: Zero (chan) => chan . is_full () , } } #[doc = " Returns the number of messages in the channel."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::channel();"] #[doc = ""] #[doc = " assert_eq!(recv.len(), 0);"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert_eq!(recv.len(), 1);"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn len (& self) -> usize { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . len () , ReceiverFlavor :: List (chan) => chan . len () , ReceiverFlavor :: Zero (chan) => chan . len () , } } #[doc = " If the channel is bounded, returns its capacity."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = mpmc::sync_channel(3);"] #[doc = ""] #[doc = " assert_eq!(recv.capacity(), Some(3));"] #[doc = ""] #[doc = " let handle = thread::spawn(move || {"] #[doc = "     send.send(1u8).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " handle.join().unwrap();"] #[doc = ""] #[doc = " assert_eq!(recv.capacity(), Some(3));"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn capacity (& self) -> Option < usize > { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . capacity () , ReceiverFlavor :: List (chan) => chan . capacity () , ReceiverFlavor :: Zero (chan) => chan . capacity () , } } #[doc = " Returns `true` if receivers belong to the same channel."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc;"] #[doc = ""] #[doc = " let (_, rx1) = mpmc::channel::<i32>();"] #[doc = " let (_, rx2) = mpmc::channel::<i32>();"] #[doc = ""] #[doc = " assert!(rx1.same_channel(&rx1));"] #[doc = " assert!(!rx1.same_channel(&rx2));"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn same_channel (& self , other : & Receiver < T >) -> bool { match (& self . flavor , & other . flavor) { (ReceiverFlavor :: Array (a) , ReceiverFlavor :: Array (b)) => a == b , (ReceiverFlavor :: List (a) , ReceiverFlavor :: List (b)) => a == b , (ReceiverFlavor :: Zero (a) , ReceiverFlavor :: Zero (b)) => a == b , _ => false , } } #[doc = " Returns an iterator that will block waiting for messages, but never"] #[doc = " [`panic!`]. It will return [`None`] when the channel has hung up."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(mpmc_channel)]"] #[doc = ""] #[doc = " use std::sync::mpmc::channel;"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let (send, recv) = channel();"] #[doc = ""] #[doc = " thread::spawn(move || {"] #[doc = "     send.send(1).unwrap();"] #[doc = "     send.send(2).unwrap();"] #[doc = "     send.send(3).unwrap();"] #[doc = " });"] #[doc = ""] #[doc = " let mut iter = recv.iter();"] #[doc = " assert_eq!(iter.next(), Some(1));"] #[doc = " assert_eq!(iter.next(), Some(2));"] #[doc = " assert_eq!(iter.next(), Some(3));"] #[doc = " assert_eq!(iter.next(), None);"] #[doc = " ```"] #[unstable (feature = "mpmc_channel" , issue = "126840")] pub fn iter (& self) -> Iter < '_ , T > { Iter { rx : self } } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > Drop for Receiver < T > { fn drop (& mut self) { unsafe { match & self . flavor { ReceiverFlavor :: Array (chan) => chan . release (| c | c . disconnect_receivers ()) , ReceiverFlavor :: List (chan) => chan . release (| c | c . disconnect_receivers ()) , ReceiverFlavor :: Zero (chan) => chan . release (| c | c . disconnect ()) , } } } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > Clone for Receiver < T > { fn clone (& self) -> Self { let flavor = match & self . flavor { ReceiverFlavor :: Array (chan) => ReceiverFlavor :: Array (chan . acquire ()) , ReceiverFlavor :: List (chan) => ReceiverFlavor :: List (chan . acquire ()) , ReceiverFlavor :: Zero (chan) => ReceiverFlavor :: Zero (chan . acquire ()) , } ; Receiver { flavor } } } #[unstable (feature = "mpmc_channel" , issue = "126840")] impl < T > fmt :: Debug for Receiver < T > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . pad ("Receiver { .. }") } } #[cfg (test)] mod tests ;